// UI strings for the custom widgets (i18next) and the header language switcher.
//
// Page content is translated at build time by Sphinx (textbook/locale/*.po);
// this file only covers text generated by our own JavaScript. Strings live in
// locales.js. Usage from any widget:  bookI18n.t("exercises.evaluate")
//
// Jupyter Book includes every _static/*.js in arbitrary order, so i18next is
// initialised lazily on the first t() call instead of at load time.
(function () {
  // `dir` is the build sub-directory of each language (see scripts/i18n.py).
  const LANGUAGES = [
    { code: "en", dir: "", label: "English" },
    { code: "zh-CN", dir: "zh_CN", label: "简体中文" },
  ];

  const lang = (document.documentElement.lang || "en").replace("_", "-");
  const current = LANGUAGES.find((l) => l.code.toLowerCase() === lang.toLowerCase()) || LANGUAGES[0];
  let ready = false;

  function init() {
    if (ready) return;
    ready = true;
    i18next.init({
      lng: current.code,
      fallbackLng: "en",
      supportedLngs: LANGUAGES.map((l) => l.code),
      resources: window.BOOK_I18N_RESOURCES || {},
      interpolation: { escapeValue: false },
      initImmediate: false,
      initAsync: false,
    });
  }

  function t(key, options) {
    if (!window.i18next) return key;
    init();
    return i18next.t(key, options);
  }

  // Map the current page to the same page in another language build.
  function urlFor(target) {
    const opts = document.getElementById("documentation_options");
    const buildRoot = new URL((opts && opts.dataset.url_root) || "./", location.href);
    const page = location.href.slice(buildRoot.href.length);
    const depth = current.dir ? current.dir.split("/").length : 0;
    const siteRoot = new URL("../".repeat(depth) || "./", buildRoot);
    return new URL((target.dir ? target.dir + "/" : "") + page, siteRoot).href;
  }

  function addSwitcher() {
    const header = document.querySelector(".header-article__right");
    if (!header) return;

    const items = LANGUAGES.map((l) => {
      const active = l === current ? ' aria-current="true"' : "";
      return (
        '<li><a class="headerbtn" href="' + urlFor(l) + '" lang="' + l.code + '"' + active + ">" +
        '<span class="headerbtn__text-container">' + l.label + "</span></a></li>"
      );
    }).join("");

    const menu = document.createElement("div");
    menu.className = "menu-dropdown menu-dropdown-language-buttons";
    menu.innerHTML =
      '<button class="headerbtn menu-dropdown__trigger" aria-label="' + t("switcher.label") + '">' +
      '<i class="fas fa-language"></i></button>' +
      '<div class="menu-dropdown__content"><ul>' + items + "</ul></div>";
    header.prepend(menu);
  }

  window.bookI18n = { t, language: current.code };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", addSwitcher);
  } else {
    addSwitcher();
  }
})();
